// currentHash is the hash of the CURRENT window of length m
// powHigh   = B^(m-1) mod P, precomputed once for the window length
// outgoing  = value of the character leaving the window (leftmost)
// incoming  = value of the character entering the window (new rightmost)
long long rollHash(long long currentHash, long long outgoing, long long incoming,
                    long long powHigh, long long B, long long P) {
    long long h = currentHash - (outgoing * powHigh) % P;  // remove outgoing contribution
    h %= P;
    if (h < 0) h += P;              // C++'s % can return negative for negative operands
    h = (h * B) % P;                // shift everything left by one position
    h = (h + incoming) % P;         // add the incoming character
    return h;
}

// C++ Rolling Hash with O(1) substring queries (single hash)
class RollingHash {
    vector<long long> prefixHash; // prefixHash[i] = hash of s[0..i-1]
    vector<long long> power;      // power[i] = B^i mod P
    long long B, P;

public:
    RollingHash(const string& s, long long base, long long mod) : B(base), P(mod) {
        int n = (int)s.size();
        prefixHash.assign(n + 1, 0);
        power.assign(n + 1, 1);

        for (int i = 0; i < n; i++) {
            prefixHash[i + 1] = (prefixHash[i] * B + charValue(s[i])) % P;
            power[i + 1] = (power[i] * B) % P;
        }
    }

    static long long charValue(char c) {
        return (long long)(c - 'a' + 1); // start at 1, never map a character to 0
    }

    // hash of s[l..r], inclusive, 0-indexed
    long long substringHash(int l, int r) const {
        long long high = prefixHash[r + 1];
        long long low = (prefixHash[l] * power[r - l + 1]) % P;
        long long result = (high - low) % P;
        if (result < 0) result += P;   // guard against negative results from %
        return result;
    }
};

// Two independent rolling hashes combined for a much lower collision probability
struct DoubleHash {
    RollingHash h1, h2;
    DoubleHash(const string& s)
        : h1(s, 131, 1000000007), h2(s, 137, 998244353) {}

    pair<long long, long long> substringHash(int l, int r) const {
        return { h1.substringHash(l, r), h2.substringHash(l, r) };
    }
};

// Two substrings are treated as equal only when BOTH hashes match
bool equalSubstrings(const DoubleHash& dh, int l1, int r1, int l2, int r2) {
    return dh.substringHash(l1, r1) == dh.substringHash(l2, r2);
}
